messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
Here is the complete, self-contained HTML file.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #loading {
            position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
            color: white; font-family: sans-serif; font-size: 24px; font-weight: bold;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="loading">Loading Race...</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const START_Z = 20;
        const FINISH_Z = -TRACK_LENGTH;
        const CAMERA_OFFSET_X = 15;
        const CAMERA_HEIGHT = 10;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);
        document.getElementById('loading').style.display = 'none';

        // --- Lights ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(20, 50, 20);
        dirLight.castShadow = true;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 500);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x33aa33 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = -TRACK_LENGTH / 2 + 20;
        ground.receiveShadow = true;
        scene.add(ground);

        // Road
        const roadGeo = new THREE.PlaneGeometry(30, 500);
        const roadMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const road = new THREE.Mesh(roadGeo, roadMat);
        road.rotation.x = -Math.PI / 2;
        road.position.z = -TRACK_LENGTH / 2 + 20;
        road.position.y = 0.05; // Slightly above ground
        road.receiveShadow = true;
        scene.add(road);

        // Finish Line
        const finishGroup = new THREE.Group();
        const lineGeo = new THREE.PlaneGeometry(30, 4);
        const lineMat = new THREE.MeshBasicMaterial({ color: 0xffffff }); // White base

        // Checkerboard pattern logic
        for(let i=0; i<15; i++) {
            for(let j=0; j<2; j++) {
                const checkGeo = new THREE.PlaneGeometry(2, 2);
                const checkMat = new THREE.MeshBasicMaterial({ color: i % 2 === j % 2 ? 0xffffff : 0x000000 });
                const check = new THREE.Mesh(checkGeo, checkMat);
                check.position.set(-14 + i*2, 0.06, -2 + j*2);
                check.rotation.x = -Math.PI / 2;
                finishGroup.add(check);
            }
        }
        finishGroup.position.z = FINISH_Z;
        scene.add(finishGroup);

        // Finish Banner
        const bannerGeo = new THREE.BoxGeometry(30, 2, 0.5);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0xffaa00 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(0, 5, FINISH_Z);
        finishGroup.add(banner);

        // --- Car Factory ---
        function createCar(colorHex) {
            const carGroup = new THREE.Group();

            // Body
            const bodyGeo = new THREE.BoxGeometry(2.5, 1.2, 5);
            const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 1;
            body.castShadow = true;
            carGroup.add(body);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(2, 0.8, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 2, -0.5);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                [-1.3, 0.6, 1.5], [1.3, 0.6, 1.5],
                [-1.3, 0.6, -1.5], [1.3, 0.6, -1.5]
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(...pos);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        // --- Race Logic ---
        const blueCarObj = { mesh: blueCar, x: -5, z: START_Z, speed: 0, maxSpeed: 0.8, accel: 0.01 };
        const redCarObj = { mesh: redCar, x: 5, z: START_Z, speed: 0, maxSpeed: 0.9, accel: 0.015 };

        scene.add(redCarObj.mesh);
        scene.add(blueCarObj.mesh);

        let raceTime = 0;
        let raceFinished = false;

        function resetRace() {
            raceTime = 0;
            raceFinished = false;
            blueCarObj.z = START_Z;
            redCarObj.z = START_Z;
            blueCarObj.speed = 0;
            redCarObj.speed = 0;

            blueCarObj.mesh.position.set(blueCarObj.x, 0, blueCarObj.z);
            redCarObj.mesh.position.set(redCarObj.x, 0, redCarObj.z);

            // Reset rotations
            blueCarObj.mesh.rotation.set(0,0,0);
            redCarObj.mesh.rotation.set(0,0,0);
        }

        function updatePhysics() {
            if (raceFinished) return;

            // Blue Car Logic (Leads early)
            if (blueCarObj.speed < blueCarObj.maxSpeed) {
                blueCarObj.speed += blueCarObj.accel;
            }
            blueCarObj.z -= blueCarObj.speed;

            // Red Car Logic (Accelerates mid-race)
            // Mid-race is roughly at z = -50. 
            if (redCarObj.z < -40) {
                redCarObj.accel = 0.02; // Turbo boost
                redCarObj.maxSpeed = 1.05; // Higher top speed
            }
            if (redCarObj.speed < redCarObj.maxSpeed) {
                redCarObj.speed += redCarObj.accel;
            }
            redCarObj.z -= redCarObj.speed;

            // Apply positions
            blueCarObj.mesh.position.z = blueCarObj.z;
            redCarObj.mesh.position.z = redCarObj.z;

            // Check Win Condition
            if (redCarObj.z <= FINISH_Z || blueCarObj.z <= FINISH_Z) {
                raceFinished = true;
                setTimeout(resetRace, 2000); // Wait 2 seconds then reset
            }
        }

        function updateCamera() {
            // Average Z position of both cars
            const avgZ = (blueCarObj.z + redCarObj.z) / 2;

            // Camera follows behind the group
            camera.position.z = avgZ + 15;
            camera.position.x = CAMERA_OFFSET_X;
            camera.position.y = CAMERA_HEIGHT;

            // Look at the point between them slightly ahead
            camera.lookAt(0, 0, avgZ - 20);
        }

        // --- Animation Loop ---
        function animate() {
            requestAnimationFrame(animate);

            updatePhysics();
            updateCamera();

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();

    </script>
</body>
</html>
```
